# Shared list of maule waveform/template pairs for TREMOR and DMASS sweeps.
#
# This file is meant to be sourced from run_maule_tremor.sh and
# run_maule_dmass.sh. It defines:
#   - WAVEFORM_DIR   : directory holding the tremor waveform .bin files
#   - TEMPLATE_DIR   : directory holding the tremor template .bin files
#   - CASES          : array of "<waveform.bin> <queries.bin> <window_length>"
#
# Each active CASES line is one job configuration (per threshold / nodes /
# replication group combo). Every other channel/station pair is listed
# below as a commented line; uncomment to add it to the sweep.
# Most entries are auto-filled from template metadata (fmin1/fmax12).

WAVEFORM_DIR="/path/to/data/maule/waveforms"
TEMPLATE_DIR="/path/to/data/maule/templates"

